1	/* The gallery's own rules. Its pages are placeholders, so what's real on
2	   screen is the layout's: grey blocks stand where a page's content would go. */
3	
4	.skeleton {
5	  display: block; inline-size: var(--w, 100%); block-size: var(--space-3);
6	  background: var(--surface-sunken); border-radius: var(--radius-sm);
7	}
8	.skeleton.title { block-size: var(--space-6); }
9	.skeleton.control { block-size: var(--control-md); border-radius: var(--radius-md); }
10	.skeleton.block { block-size: calc(8 * var(--space-4)); border-radius: var(--radius-lg); }
11	/* A heading's placeholder keeps the heading's own line, so the Close beside
12	   it lines up as it would with words. */
13	h2 > .skeleton { display: inline-block; vertical-align: middle; block-size: 1em; }
14	
15	/* workspace and window: placeholders that fill the page the layout gives them. */
16	.gallery-fill { flex: 1; min-block-size: 0; }
17	.skeleton.fill { block-size: auto; min-block-size: 0; border-radius: var(--radius-lg); }
